    DataTable dataTable = JsonConvert.DeserializeObject<DataTable>(jsonObject);

    var workbook = new XLWorkbook();
    IXLWorksheet worksheet = workbook.Worksheets.Add("Data");
    int colNumber = 1;
    foreach (DataColumn col in dataTable.Columns)
    {
        worksheet.Cell(1, colNumber++).Value = col.ColumnName;

    }
    int rowNumber = 2;
    foreach (DataRow row in dataTable.Rows)
    {
        colNumber = 1;
        foreach (var item in row.ItemArray)
        {
            worksheet.Cell(rowNumber, colNumber++).Value = item;
        }
        rowNumber++;
    }
    worksheet.Columns().AdjustToContents();  // Adjust column width
    worksheet.Rows().AdjustToContents();
    using (var stream = new MemoryStream())
    {
        workbook.SaveAs(stream);
        var content = stream.ToArray();
        return content;
    }

